#include <stdio.h>
#include <stdlib.h>

enum { OK = 0, ERR_OPEN = -1, ERR_MEM = -2, ERR_READ = -3, ERR_CLOSE = -4 };

int process_file(const char *path) {
    int status = OK;
    FILE *f = NULL;                      /* "not acquired". */
    char *buf = NULL;

    f = fopen(path, "r");
    if (f == NULL) { status = ERR_OPEN; goto cleanup; }

    buf = malloc(4096);
    if (buf == NULL) { status = ERR_MEM; goto cleanup; }

    if (fgets(buf, 4096, f) == NULL && ferror(f)) { status = ERR_READ; goto cleanup; }
    /* ... parse; on failure set status and goto cleanup ... */

cleanup:                                 /* reverse order of acquisition. */
    free(buf);                           /* free(NULL) is a no-op. */
    if (f != NULL && fclose(f) != 0 && status == OK) status = ERR_CLOSE;
    return status;                       /* keeps the FIRST error. */
}
